pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testRegression_property() public {
        c.Initialized();
        bool ok;
        try c.SetMinSum(100) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
